head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.strQueryId = "";
scwin.strBzCalndDd = "";

// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        btn_Excel.show("");
        lab_comment.hide();
        lab_comment_new.hide();
        $c.cm.PanelToGroupBox(panel_Top);
        await scwin.setHeader();
        await scwin.getDate();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05322.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_getDate_OnLoadError
 * @description dts_getDate 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_getDate_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_getDate);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05322.dts_getDate_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_getDate_OnLoadCompleted
 * @description dts_getDate 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_getDate_OnLoadCompleted = async function(rowcount) {
    try {
        scwin.strBzCalndDd = dts_getDate.getCellData(1, "CALND_DD");
        tbx_changeListDd.setValue(scwin.strBzCalndDd);
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05322.dts_getDate_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_List);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05322.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05322.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name btn_changeListDd_onclick
 * @description btn_changeListDd 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_changeListDd_onclick = function() {
    try {
        popUpCalendar2(tbx_changeListDd);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05322.btn_changeListDd_onclick" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05322.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Excel_onclick = async function() {
    try {
        await scwin.excelDown();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05322.btn_Excel_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name getDate
 * @description 익일영업일 가져옴
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getDate = async function() {
    const sbmOptions = {
        id : "sbm_dts_getDate",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_getDate=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name listSync
 * @description 현재 조회일이 익일영업일과 같은경우 -> 신규임시테이블 데이터 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    // 현재 조회일이 익일영업일과 같은경우 -> 신규임시테이블 데이터 조회
    if (tbx_changeListDd.getValue() === scwin.strBzCalndDd) {
        scwin.strQueryId = "lds.stf.lstproc.lstlst.select.etf.chglist.recv.newtempcount";
        lab_comment.hide();
        lab_comment_new.show("");
        // 현재 조회일이 익일영업일과 다른경우 -> 기존테이블 데이터 조회

    } else {
        scwin.strQueryId = "lds.stf.lstproc.lstlst.select.etf.chglist.recv.count";
        lab_comment_new.hide();
        lab_comment.show("");
    }
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name setHeader
 * @description set Header 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setHeader = async function() {
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // alert(dts_List.text+" dts_List.text");

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name excelDown
 * @description 정보를 excel로 다운 받는다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.excelDown = async function() {
    if (dts_List.getRowCount() > 0) {
        $c.stf.doLogSave("ULDSTF05322.xml", SCREN_PROCS_TP_CD_07);
        $c.data.downloadGridViewExcel(grd_List, {fileName: "ETF 변경상장 수량 ", type: "3"});
    } else {
        await $c.win.alert("해당데이터가 없습니다. 조회후 다운받으십시요.");
    }
};
